function readFactors($){return [1,2,3,4].map(i=>{const value=$('#lg-ninej-factor'+i)?.value;if(!reps.some(([key])=>key===value))throw Error('四个因子请从 Dynkin 标签 p + q ≤ 4 的 15 种表示中选择。');return value.split(',').map(Number);});}
